	// variable.UNIT_WORDS: units given in other words, in UDUNITS (before those of UNITS)
	var UNIT_WORDS = {'\u00b0C': 'degC', '\u00b0F': 'degF', '\u00b0': 'degree', 'deg C': 'degC', 'deg F': 'degF'};
